function youtubeVideo(raw) {
  const url = typeof raw === "string" ? raw.trim() : "";
  if (url.length > 500 || /\s/.test(url)) throw new Error("Supply one full YouTube video URL");
  const short = url.match(/^https:\/\/youtu\.be\/([A-Za-z0-9_-]{11})(?:[?#].*)?$/i);
  const path = url.match(
    /^https:\/\/(?:www\.|m\.)?youtube\.com\/(?:shorts|live)\/([A-Za-z0-9_-]{11})(?:[?#].*)?$/i,
  );
  const watch = url.match(/^https:\/\/(?:www\.|m\.)?youtube\.com\/watch\?([^#]*)/i);
  const values =
    watch?.[1]
      .split("&")
      .filter((part) => part.startsWith("v="))
      .map((part) => part.slice(2)) ?? [];
  const id = short?.[1] ?? path?.[1] ?? (values.length === 1 ? values[0] : "");
  if (!/^[A-Za-z0-9_-]{11}$/.test(id)) throw new Error("Supply one full YouTube video URL");
  return id;
}
const videoId = youtubeVideo($input.first().json["Full URL"]);
return [{ json: { state: { phase: "list", videoId } }, pairedItem: { item: 0 } }];

function buildCaptionRequest(state) {
  const root = "/api/v1/youtube/web_v2/";
  const query =
    state.phase === "poll"
      ? { job_id: state.job, format: "txt" }
      : state.phase === "track"
        ? { video_id: state.videoId, language_code: state.language, format: "txt" }
        : { video_id: state.videoId };
  return {
    path: root + (state.phase === "poll" ? "get_video_captions_result" : "get_video_captions"),
    request: { query },
  };
}
const { state } = $input.first().json;
const { path, request } = buildCaptionRequest(state);
const parameters = Object.entries(request.query)
  .map(([key, value]) => key + "=" + encodeURIComponent(value))
  .join("&");
return [
  {
    json: { state, url: "https://api.tikhub.io" + path + "?" + parameters },
    pairedItem: { item: 0 },
  },
];

function nextCaptionState(state, reply) {
  const payload = reply?.data;
  // Only a track request has a video and language already verified against the caption listing.
  const data =
    state.phase === "track" && typeof payload === "string"
      ? { content: payload, video_id: state.videoId, language_code: state.language, format: "txt" }
      : payload;
  if (reply?.code !== 200 || !data || typeof data !== "object" || Array.isArray(data)) {
    throw new Error("TikHub did not return YouTube captions");
  }
  const languageCode = (value) =>
    typeof value === "string" && /^(?:a\.)?[A-Za-z]{2,3}(?:-[A-Za-z0-9]{2,8}){0,3}$/.test(value);
  const requiresVideo =
    state.phase === "list" || (state.phase === "track" && data.status === "processing");
  const mismatchedVideo =
    (requiresVideo || Object.hasOwn(data, "video_id")) && data.video_id !== state.videoId;
  const mismatchedJob = state.phase === "poll" && data.job_id !== state.job;
  if (mismatchedVideo || mismatchedJob) {
    throw new Error("TikHub returned captions for a different video or job");
  }
  if (state.phase !== "poll" && data.status === "processing") {
    if (typeof data.job_id !== "string" || !/^[A-Za-z0-9_-]{8,128}$/.test(data.job_id))
      throw new Error("TikHub did not return a valid caption job");
    return {
      pending: true,
      state: { ...state, phase: "poll", job: data.job_id, pollCount: 0 },
      transcript: "",
      language: "",
    };
  }
  if (state.phase === "list") {
    if (!Array.isArray(data.captions))
      throw new Error("TikHub did not return a caption language list");
    const tracks = data.captions.map((track) => track?.language_code).filter(languageCode);
    if (!tracks.length) throw new Error("The video has no available captions");
    const language =
      tracks.find((code) => code === "en") ??
      tracks.find((code) => /^en-/i.test(code)) ??
      tracks.find((code) => code === "a.en") ??
      tracks[0];
    return {
      pending: true,
      state: { ...state, phase: "track", language },
      transcript: "",
      language: "",
    };
  }
  if (state.phase === "poll" && ["queued", "active"].includes(data.status)) {
    if (state.pollCount + 1 >= 12)
      throw new Error("TikHub caption job did not finish after 12 checks");
    return {
      pending: true,
      state: { ...state, pollCount: state.pollCount + 1 },
      transcript: "",
      language: "",
    };
  }
  if (
    (state.phase === "poll" && data.status !== "completed") ||
    (state.phase === "track" && data.status != null && data.status !== "completed")
  ) {
    throw new Error("TikHub caption processing did not complete");
  }
  const language = Object.hasOwn(data, "language_code")
    ? data.language_code
    : state.phase === "track"
      ? state.language
      : undefined;
  const transcript = typeof data.content === "string" ? data.content.trim() : "";
  const format = Object.hasOwn(data, "format")
    ? data.format
    : state.phase === "track"
      ? "txt"
      : undefined;
  if (
    !languageCode(language) ||
    (state.language && state.language !== language) ||
    format !== "txt" ||
    !transcript ||
    transcript.length > 60000
  )
    throw new Error("TikHub returned missing, mismatched or oversized caption text");
  return { pending: false, state, transcript, language };
}
const previous = $("Prepare the caption request").itemMatching(0).json.state;
return [{ json: nextCaptionState(previous, $input.first().json), pairedItem: { item: 0 } }];

function videoTitle(reply, id) {
  const current = reply?.data?.playerResponse?.videoDetails;
  if (
    reply?.code !== 200 ||
    current?.videoId !== id ||
    typeof current.title !== "string" ||
    !current.title.trim() ||
    current.title.length > 300
  ) {
    throw new Error("TikHub did not confirm the title of the submitted video");
  }
  return current.title;
}
const { state, transcript, language } = $("Check the caption response").itemMatching(0).json;
const videoId = state.videoId;
const title = videoTitle($input.first().json, videoId);
return [
  {
    json: {
      videoId,
      title,
      language,
      input: JSON.stringify({ title, caption_language: language, captions: transcript }),
    },
    pairedItem: { item: 0 },
  },
];

function summarizeCaptionResult(reply, videoId, title, language) {
  if (reply?.status !== "completed" || !Array.isArray(reply.output))
    throw new Error("OpenAI did not complete the caption summary");
  const messages = reply.output.filter((item) => item.type === "message");
  const message = messages[0];
  if (
    messages.length !== 1 ||
    message.role !== "assistant" ||
    message.status !== "completed" ||
    !Array.isArray(message.content) ||
    message.content.length !== 1 ||
    message.content[0]?.type !== "output_text"
  ) {
    throw new Error("OpenAI did not return a structured summary");
  }
  const parsed = JSON.parse(message.content[0].text);
  const validText = (text, max) => typeof text === "string" && text.trim() && text.length <= max;
  if (
    !validText(parsed?.summary, 2200) ||
    !Array.isArray(parsed?.key_points) ||
    parsed.key_points.length < 1 ||
    parsed.key_points.length > 6 ||
    !parsed.key_points.every((point) => validText(point, 400))
  ) {
    throw new Error("OpenAI returned an invalid caption summary");
  }
  return {
    videoId,
    videoUrl: "https://www.youtube.com/watch?v=" + videoId,
    title,
    captionLanguage: language,
    summary: parsed.summary.trim(),
    keyPoints: parsed.key_points.map((point) => point.trim()),
  };
}
const { videoId, title, language } = $("Prepare a summary from checked captions").itemMatching(
  0,
).json;
return [
  {
    json: summarizeCaptionResult($input.first().json, videoId, title, language),
    pairedItem: { item: 0 },
  },
];
